package com.simibubi.create.test;

import com.mojang.blaze3d.platform.InputConstants;
import com.simibubi.create.*;
import com.simibubi.create.content.logistics.filter.*;
import com.simibubi.create.content.logistics.item.filter.attribute.*;
import net.fabricmc.fabric.api.client.gametest.v1.context.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;

final class AttributeFilterRenderingTest {
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 890 6 12");context.waitFor(client->Math.abs(client.player.getX()-890.5)<0.1&&client.level.isLoaded(new BlockPos(890,4,5)),300);server.runCommand("fill 885 3 1 899 3 16 minecraft:smooth_quartz");server.runCommand("tp @p 890 4 12");server.runCommand("gamemode survival @p");server.runCommand("item replace entity @p weapon.mainhand with create:attribute_filter");
        server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.getInventory().setItem(9,new ItemStack(Items.APPLE,16));player.getInventory().setItem(10,new ItemStack(RuntimeWoodFixtures.ASSEMBLY_BLANK,8));player.inventoryMenu.broadcastChanges();});context.waitFor(client->client.player.getMainHandItem().is(AllItems.ATTRIBUTE_FILTER)&&client.player.getInventory().getItem(9).getCount()==16,200);context.getInput().lookAt(new BlockPos(890,15,5));open(context);
        shiftClick(context,0);context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.available().stream().anyMatch(attribute->attribute.getType()==AllItemAttributeTypes.CONSUMABLE),200);select(context,AllItemAttributeTypes.CONSUMABLE);context.clickScreenButton("+");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.selected().size()==1,200);context.clickScreenButton("AND");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.mode()==AttributeFilterWhitelistMode.WHITELIST_CONJ,200);context.takeScreenshot("create-vulkan-attribute-filter-food");
        var before=context.computeOnClient(client->((AttributeFilterMenu)client.player.containerMenu).revision());var reload=new java.util.concurrent.atomic.AtomicReference<java.util.concurrent.CompletableFuture<Void>>();server.runOnServer(actual->reload.set(actual.reloadResources(actual.getPackRepository().getSelectedIds())));context.waitFor(client->reload.get()!=null&&reload.get().isDone()&&client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.revision()>before&&menu.selected().size()==1,600);reload.get().join();
        shiftClick(context,1);context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.available().stream().anyMatch(attribute->attribute.getType()==RuntimeWoodFixtures.ADDON_ATTRIBUTE),200);select(context,RuntimeWoodFixtures.ADDON_ATTRIBUTE);context.clickScreenButton("−");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.selected().size()==2&&menu.selected().get(1).inverted(),200);context.takeScreenshot("create-vulkan-attribute-filter-addon");
        context.clickScreenButton("✓");context.waitFor(client->client.gui.screen()==null&&client.player.getMainHandItem().has(AllDataComponents.ATTRIBUTE_FILTER_MATCHED_ATTRIBUTES),200);context.runOnClient(client->{var filter=FilterItemStack.of(client.player.getMainHandItem());if(!filter.test(client.level,new ItemStack(Items.APPLE))||filter.test(client.level,new ItemStack(RuntimeWoodFixtures.ASSEMBLY_BLANK)))throw new AssertionError("Saved all/inverted predicates differ on client");if(client.player.getInventory().getItem(9).getCount()!=16||client.player.getInventory().getItem(10).getCount()!=8)throw new AssertionError("Ghost reference consumed actual items");var tooltip=client.player.getMainHandItem().getTooltipLines(Item.TooltipContext.of(client.level),client.player,TooltipFlag.NORMAL).stream().map(net.minecraft.network.chat.Component::getString).toList();if(tooltip.stream().noneMatch(line->line.contains("eaten")))throw new AssertionError("Attribute tooltip is not translated: "+tooltip);});
        open(context);context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.selected().size()==2&&menu.mode()==AttributeFilterWhitelistMode.WHITELIST_CONJ,200);context.clickScreenButton("NOT");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.mode()==AttributeFilterWhitelistMode.BLACKLIST,200);context.clickScreenButton("×");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.selected().isEmpty(),200);context.takeScreenshot("create-vulkan-attribute-filter-cleared");
        server.runOnServer(ignored->{var player=world.getConnection().getServerLevel().getServer().getPlayerList().getPlayers().getFirst();player.getInventory().setItem(9,new ItemStack(Items.BUCKET));player.containerMenu.broadcastChanges();});context.waitFor(client->client.player.getInventory().getItem(9).is(Items.BUCKET),200);shiftClick(context,0);context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.available().stream().anyMatch(attribute->attribute.getType()==AllItemAttributeTypes.HAS_FLUID),200);select(context,AllItemAttributeTypes.HAS_FLUID);context.waitTicks(3);context.takeScreenshot("create-vulkan-attribute-filter-empty-container");
        context.clickScreenButton("OR");context.waitFor(client->client.player.containerMenu instanceof AttributeFilterMenu menu&&menu.mode()==AttributeFilterWhitelistMode.WHITELIST_DISJ,200);context.getInput().pressKey(InputConstants.KEY_ESCAPE);context.waitFor(client->client.gui.screen()==null&&!client.player.getMainHandItem().has(AllDataComponents.ATTRIBUTE_FILTER_MATCHED_ATTRIBUTES),200);server.runCommand("gamemode spectator @p");
    }
    private static void open(ClientGameTestContext context){context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.gui.screen() instanceof AttributeFilterScreen,200);context.waitTicks(2);}
    private static void shiftClick(ClientGameTestContext context,int slot){context.runOnClient(client->{var screen=(AttributeFilterScreen)client.gui.screen();var point=screen.slotPosition(slot);var event=new net.minecraft.client.input.MouseButtonEvent(point.x,point.y,new net.minecraft.client.input.MouseButtonInfo(InputConstants.MOUSE_BUTTON_LEFT,InputConstants.MOD_SHIFT));screen.mouseClicked(event,false);screen.mouseReleased(event);});}
    private static void select(ClientGameTestContext context,ItemAttributeType type){context.runOnClient(client->{var screen=(AttributeFilterScreen)client.gui.screen();var available=screen.getMenu().available();for(int i=0;i<available.size();i++)if(available.get(i).getType()==type){screen.selectAttribute(i);return;}throw new AssertionError("Server did not synchronize selected attribute type");});}
}
